// TypeScript Version: 4.1

import dorgbr = require( './index' );

// TESTS //

// The function returns a number...
{
	const A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	const TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	const WORK = new Float64Array( 10 );

	dorgbr( 'column-major', 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectType number
	dorgbr( 'column-major', 'P', 4, 4, 5, A, 4, TAU, WORK, 10 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	const TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	const WORK = new Float64Array( 10 );

	dorgbr( 'foo', 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 5, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( true, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( false, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( null, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( undefined, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( [], 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( {}, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( ( x: number ): number => x, 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is neither 'Q' nor 'P'...
{
	const A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	const TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	const WORK = new Float64Array( 10 );

	dorgbr( 'column-major', 'foo', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', 'q', 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', 5, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', true, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', false, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', null, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', undefined, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', [], 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', {}, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
	dorgbr( 'column-major', ( x: number ): number => x, 4, 3, 3, A, 4, TAU, WORK, 10 ); // $ExpectError
}

