// Attached to the main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	const TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	const WORK = new Float64Array( 10 );

	dorgbr.ndarray( 'Q', 4, 3, 3, A, 1, 4, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectType number
	dorgbr.ndarray( 'P', 4, 4, 5, A, 1, 4, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectType number
}

